-- BiasharaOS multi-tenant foundation. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create type public.app_role as enum ('owner','admin','manager','staff','member');
create type public.membership_status as enum ('active','invited','suspended');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,county text,phone text,currency text not null default 'KES',created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.memberships(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role public.app_role not null default 'staff',status public.membership_status not null default 'active',created_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.branches(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,address text,phone text,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,sku text not null,name text not null,category text,unit_price numeric(14,2) not null default 0,cost_price numeric(14,2) not null default 0,stock_qty numeric(14,3) not null default 0,reorder_level numeric(14,3) not null default 0,expiry_date date,created_at timestamptz not null default now(),unique(organization_id,sku));
create table public.customers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,phone text,email text,created_at timestamptz not null default now());
create table public.invoices(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid references public.customers(id),invoice_no text not null,amount numeric(14,2) not null default 0,status text not null default 'draft',due_date date,created_at timestamptz not null default now(),unique(organization_id,invoice_no));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,user_id uuid references auth.users(id),action text not null,entity_type text,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index memberships_user_idx on public.memberships(user_id);create index products_org_idx on public.products(organization_id);create index customers_org_idx on public.customers(organization_id);create index invoices_org_idx on public.invoices(organization_id);
create or replace function public.is_org_member(target_org uuid) returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from public.memberships m where m.organization_id=target_org and m.user_id=auth.uid() and m.status='active')$$;
create or replace function public.has_org_role(target_org uuid, roles public.app_role[]) returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from public.memberships m where m.organization_id=target_org and m.user_id=auth.uid() and m.status='active' and m.role=any(roles))$$;
alter table public.organizations enable row level security;alter table public.profiles enable row level security;alter table public.memberships enable row level security;alter table public.branches enable row level security;alter table public.products enable row level security;alter table public.customers enable row level security;alter table public.invoices enable row level security;alter table public.audit_logs enable row level security;
create policy "members read organizations" on public.organizations for select using (public.is_org_member(id));
create policy "users read own profile" on public.profiles for select using (id=auth.uid());
create policy "users update own profile" on public.profiles for update using (id=auth.uid());
create policy "members read memberships" on public.memberships for select using (user_id=auth.uid() or public.is_org_member(organization_id));
create policy "members read branches" on public.branches for select using (public.is_org_member(organization_id));
create policy "members read products" on public.products for select using (public.is_org_member(organization_id));
create policy "managers write products" on public.products for all using (public.has_org_role(organization_id,array['owner','admin','manager']::public.app_role[])) with check (public.has_org_role(organization_id,array['owner','admin','manager']::public.app_role[]));
create policy "members read customers" on public.customers for select using (public.is_org_member(organization_id));
create policy "managers write customers" on public.customers for all using (public.has_org_role(organization_id,array['owner','admin','manager']::public.app_role[])) with check (public.has_org_role(organization_id,array['owner','admin','manager']::public.app_role[]));
create policy "members read invoices" on public.invoices for select using (public.is_org_member(organization_id));
create policy "managers write invoices" on public.invoices for all using (public.has_org_role(organization_id,array['owner','admin','manager']::public.app_role[])) with check (public.has_org_role(organization_id,array['owner','admin','manager']::public.app_role[]));
create policy "members read audit" on public.audit_logs for select using (public.is_org_member(organization_id));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name') on conflict(id) do nothing; return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Organization creation should be performed by a controlled server action after signup; do not grant arbitrary clients permission to create tenants.
